            st32!(c, fr, fm, va.wrapping_add(0x80), v1 as u32, fr.pc(0x214), ic0 + 3, 5); // sw $v1, 0x80($v0)
            v1 = (v1 & HI) | 0x80; // addi $v1, $zero, 0x80 (insn 4)
