    // Region 6 of tfrag_proc (0x2805e0), 0x280b24..0x280c50, SPEED STYLE: GPR low halves and 128-bit registers in locals, memory through one
    // window per block (every guard before any effect), every modified register written back by flush! at every exit and deopt.
    // No VU0 flag ops here: vitof0 of these values (|v| < 2^21) is exact integer bit work; pextlh/psraw are plain bit ops.
    use super::gen::*;
    use crate::cpu::Cpu;
    use crate::hs::{deopt, Frame};
    use crate::hs_fast::{lo, sx32, wlo, Fm};
    
    pub fn region(c: &mut Cpu, fr: &Frame) -> bool {
        let entry = match c.pc.wrapping_sub(fr.base) {
            0x544 => 0,
            0x5bc => 1,
            0x610 => 4,
            _ => return false,
        };
        run(c, fr, entry)
    }
    
    // VU register lanes <-> 128-bit value (lane 0 = bits 0..31, as V::ld reads them).
    #[inline(always)]
    fn pk(a: [u32; 4]) -> u128 {
        (a[0] as u128) | ((a[1] as u128) << 32) | ((a[2] as u128) << 64) | ((a[3] as u128) << 96)
    }
    
    #[inline(always)]
    fn up(x: u128) -> [u32; 4] {
        [x as u32, (x >> 32) as u32, (x >> 64) as u32, (x >> 96) as u32]
    }
    
    // PEXTLH rd, rs, $zero on the lower doubleword: halfword i of rs lands in the odd halfword of word i.
    #[inline(always)]
    fn pext0(x: u64) -> u128 {
        let mut r: u128 = 0;
        for i in 0..4 {
            r |= (((x >> (16 * i)) & 0xffff) as u128) << (32 * i + 16);
        }
        r
    }
    
    // PSRAW by 10 on each of the four words.
    #[inline(always)]
    fn psraw10(v: u128) -> u128 {
        let mut r: u128 = 0;
        for i in 0..4 {
            let w = ((((v >> (32 * i)) as u32) as i32) >> 10) as u32;
            r |= (w as u128) << (32 * i);
        }
        r
    }
    
    // VITOF0 of one 32-bit int; exact for |v| < 2^24 (all values here are below 2^21).
    #[inline(always)]
    fn itof0(v: u32) -> u32 {
        let i = v as i32;
        if i == 0 {
            return 0;
        }
        let m = i.unsigned_abs();
        let e = 31 - m.leading_zeros();
        (v & 0x8000_0000) | ((e + 127) << 23) | ((m << (23 - e)) & 0x7f_ffff)
    }
    
    // VITOF0.xyz: lanes x, y, z (bits 0..95) converted, w kept.
    #[inline(always)]
    fn itof_xyz(v: u128) -> u128 {
        let mut r: u128 = (((v >> 96) as u32) as u128) << 96;
        for i in 0..3 {
            r |= (itof0((v >> (32 * i)) as u32) as u128) << (32 * i);
        }
        r
    }
    
